function chainLoopStart(next, head) {
    const visited = new Set();
    let station = head;
    while (station !== -1) {
        if (visited.has(station))
            return station;
        visited.add(station);
        station = next[station];
    }
    return -1;
}

function chainLoopStart(next, head) {
    let slow = head;
    let fast = head;
    while (true) {
        if (fast === -1 || next[fast] === -1)
            return -1;
        slow = next[slow];
        fast = next[next[fast]];
        if (slow === fast)
            break;
    }
    let entry = head;
    while (entry !== slow) {
        entry = next[entry];
        slow = next[slow];
    }
    return entry;
}
